<?php
require_once __DIR__.'/../includes/functions.php';require_login();require_once __DIR__.'/../config/database.php';if($_SERVER['REQUEST_METHOD']!=='POST')redirect('careers/index.php');verify_csrf();$assessmentId=(int)($_POST['assessment_id']??0);$userId=(int)current_user()['user_id'];
$st=$pdo->prepare("SELECT a.*,j.role_name FROM assessments a JOIN job_roles j ON j.job_role_id=a.job_role_id WHERE a.assessment_id=? AND a.user_id=? AND a.status='completed'");$st->execute([$assessmentId,$userId]);$assessment=$st->fetch();if(!$assessment){flash('Assessment not found.','error');redirect('assessment/history.php');}
$existing=$pdo->prepare('SELECT roadmap_id FROM roadmaps WHERE assessment_id=? AND user_id=? LIMIT 1');$existing->execute([$assessmentId,$userId]);if($id=$existing->fetchColumn()){flash('A roadmap already exists for this assessment.');redirect('roadmap/index.php?id='.$id);}
$st=$pdo->prepare('SELECT ar.skill_id,ar.current_level,ar.required_level,ar.gap_level,s.skill_name FROM assessment_results ar JOIN skills s ON s.skill_id=ar.skill_id WHERE ar.assessment_id=? ORDER BY ar.gap_level DESC');$st->execute([$assessmentId]);$gaps=$st->fetchAll();
$pdo->beginTransaction();try{$st=$pdo->prepare('INSERT INTO roadmaps (user_id,job_role_id,assessment_id,title,start_date,target_date) VALUES (?,?,?,?,CURDATE(),DATE_ADD(CURDATE(),INTERVAL 8 WEEK))');$st->execute([$userId,$assessment['job_role_id'],$assessmentId,'8-week plan for '.$assessment['role_name']]);$roadmapId=(int)$pdo->lastInsertId();$insert=$pdo->prepare('INSERT INTO roadmap_items (roadmap_id,skill_id,project_id,resource_id,item_type,title,description,priority,status,sequence_number) VALUES (?,?,?,?,?,?,?,?,?,?)');$seq=1;
foreach($gaps as $gap){if((int)$gap['gap_level']<=0)continue;$skillId=(int)$gap['skill_id'];$priority=(int)$gap['gap_level']>=2?'high':'medium';$resourceStmt=$pdo->prepare('SELECT lr.resource_id,lr.title,lr.description,lr.resource_url FROM resource_skills rs JOIN learning_resources lr ON lr.resource_id=rs.resource_id WHERE rs.skill_id=? AND lr.is_active=1 ORDER BY lr.is_free DESC,lr.estimated_minutes ASC LIMIT 1');$resourceStmt->execute([$skillId]);$resource=$resourceStmt->fetch();if($resource){$insert->execute([$roadmapId,$skillId,null,$resource['resource_id'],'learn','Learn '.$gap['skill_name'],$resource['description']?:'Study the selected learning resource and make notes.',$priority,'not_started',$seq++]);}
$projectStmt=$pdo->prepare('SELECT p.project_id,p.title,p.description FROM project_skills ps JOIN projects p ON p.project_id=ps.project_id WHERE ps.skill_id=? AND p.is_active=1 ORDER BY p.difficulty ASC,p.estimated_hours ASC LIMIT 1');$projectStmt->execute([$skillId]);$project=$projectStmt->fetch();if($project){$insert->execute([$roadmapId,$skillId,$project['project_id'],null,'project',$project['title'],$project['description'],$priority,'not_started',$seq++]);}else{$insert->execute([$roadmapId,$skillId,null,null,'practice','Practice '.$gap['skill_name'],'Complete a small practical exercise and record what you learned.',$priority,'not_started',$seq++]);}}
if($seq===1){$insert->execute([$roadmapId,(int)$gaps[0]['skill_id'],null,null,'practice','Maintain your current strengths','Your self-assessed skills currently meet the configured targets. Build a small portfolio project to keep practicing.','low','not_started',$seq++]);}
$pdo->commit();create_notification($pdo,$userId,'Your roadmap is ready','A personalized roadmap was created from your '.$assessment['role_name'].' assessment.','roadmap','roadmap/index.php?id='.$roadmapId);flash('Your personalized roadmap has been generated.');redirect('roadmap/index.php?id='.$roadmapId);
}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();error_log('Roadmap generation failed: '.$e->getMessage());flash('We could not generate the roadmap. Please try again.','error');redirect('assessment/result.php?id='.$assessmentId);}
